#include "supervisor-control-v2.h"
#include <string.h>
static int nonzero16(const uint8_t *p){uint8_t v=0;size_t i;if(!p)return 0;for(i=0;i<16;i++)v|=p[i];return v!=0;}
int raya_ctl_payload_valid(const uint8_t *p,size_t n){if(!p||n<1||n>RAYA_CTL_MAX_PAYLOAD)return 0;switch(p[0]){case RAYA_CTL_HELLO:return n==39&&p[1]==0&&p[2]==0&&nonzero16(p+7)&&nonzero16(p+23);case RAYA_CTL_CHALLENGE:return n==33&&nonzero16(p+1)&&nonzero16(p+17);case RAYA_CTL_AUTH_BINDING:return n==49&&nonzero16(p+1)&&nonzero16(p+17)&&nonzero16(p+33);case RAYA_CTL_READY:return n==17&&nonzero16(p+1);case RAYA_CTL_PING:case RAYA_CTL_PONG:return n==5;case RAYA_CTL_STOP:return n==7&&p[5]==0&&p[6]<=3;case RAYA_CTL_STOPPED:return n==5;case RAYA_CTL_FATAL:return n==3&&p[1]==0;default:return 0;}}
int raya_ctl_u32_read(const uint8_t *p,size_t n,uint32_t *out){if(!p||!out||n!=4)return 0;*out=((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];return 1;}
void raya_ctl_u32_write(uint8_t out[4],uint32_t v){out[0]=(uint8_t)(v>>24);out[1]=(uint8_t)(v>>16);out[2]=(uint8_t)(v>>8);out[3]=(uint8_t)v;}
int raya_ctl_nonce_equal(const uint8_t a[16],const uint8_t b[16]){uint8_t d=0;size_t i;if(!a||!b)return 0;for(i=0;i<16;i++)d|=(uint8_t)(a[i]^b[i]);return d==0;}
int raya_ctl_accept_request_id(uint32_t prev,uint32_t in){return prev!=UINT32_MAX&&in!=0&&in==prev+1;}
int raya_ctl_step(raya_ctl_session *x,raya_ctl_event e,int identity){raya_ctl_state *s;if(!x)return 0;s=&x->state;if(e==RAYA_CTL_EV_FAILURE){if(*s==RAYA_CTL_CLOSED||*s==RAYA_CTL_PROCESS_EXITED)return 0;*s=RAYA_CTL_DEGRADED;return 1;}switch(*s){case RAYA_CTL_DISCONNECTED:if(e==RAYA_CTL_EV_CONNECT){*s=RAYA_CTL_CONNECTED;return 1;}break;case RAYA_CTL_CONNECTED:if(e==RAYA_CTL_EV_HELLO_VALID){*s=RAYA_CTL_AUTHENTICATING;return 1;}break;case RAYA_CTL_AUTHENTICATING:if(e==RAYA_CTL_EV_CHALLENGE_VALID&&!x->challenge_seen&&!x->binding_seen){x->challenge_seen=1;return 1;}if(e==RAYA_CTL_EV_BINDING_VALID&&x->challenge_seen&&!x->binding_seen){x->binding_seen=1;return 1;}if(e==RAYA_CTL_EV_IDENTITY_VERIFIED&&identity){x->identity_verified=1;return 1;}if(e==RAYA_CTL_EV_READY_VALID&&x->challenge_seen&&x->binding_seen&&x->identity_verified&&identity){*s=RAYA_CTL_READY_STATE;return 1;}break;case RAYA_CTL_READY_STATE:if(e==RAYA_CTL_EV_PING_VALID||e==RAYA_CTL_EV_PONG_VALID)return 1;if(e==RAYA_CTL_EV_STOP_SENT){*s=RAYA_CTL_STOP_REQUESTED;return 1;}break;case RAYA_CTL_STOP_REQUESTED:if(e==RAYA_CTL_EV_STOPPED_VALID){*s=RAYA_CTL_STOPPED_STATE;return 1;}break;case RAYA_CTL_STOPPED_STATE:if(e==RAYA_CTL_EV_PROCESS_EXIT_CONFIRMED){*s=RAYA_CTL_PROCESS_EXITED;return 1;}break;case RAYA_CTL_PROCESS_EXITED:if(e==RAYA_CTL_EV_CLOSE){*s=RAYA_CTL_CLOSED;return 1;}break;default:break;}return 0;}
void raya_ctl_generation_cache_init(raya_ctl_generation_cache *c){if(c)memset(c,0,sizeof(*c));}
int raya_ctl_generation_reserve(raya_ctl_generation_cache *c,const uint8_t gen[16]){size_t i;if(!c||!gen||!nonzero16(gen)||c->exhausted)return 0;for(i=0;i<c->count;i++)if(raya_ctl_nonce_equal(c->entries[i],gen))return 0;if(c->count>=RAYA_CTL_GENERATION_CACHE_CAPACITY){c->exhausted=1;return 0;}memcpy(c->entries[c->count],gen,16);c->count++;if(c->count==RAYA_CTL_GENERATION_CACHE_CAPACITY)c->exhausted=1;return 1;}
int raya_ctl_transcript_init_guarded(raya_ctl_transcript *t,raya_ctl_generation_cache *c,const uint8_t gen[16],const uint8_t sn[16]){if(!t||!c||!gen||!sn||!nonzero16(gen)||!nonzero16(sn))return 0;if(!raya_ctl_generation_reserve(c,gen))return 0;memset(t,0,sizeof(*t));memcpy(t->generation,gen,16);memcpy(t->supervisor_nonce,sn,16);return 1;}
int raya_ctl_transcript_init(raya_ctl_transcript *t,const uint8_t gen[16],const uint8_t sn[16]){if(!t||!gen||!sn||!nonzero16(gen)||!nonzero16(sn))return 0;memset(t,0,sizeof(*t));memcpy(t->generation,gen,16);memcpy(t->supervisor_nonce,sn,16);return 1;}
int raya_ctl_accept_hello(raya_ctl_transcript *t,const uint8_t *p,size_t n){if(!t||!raya_ctl_payload_valid(p,n)||p[0]!=RAYA_CTL_HELLO||t->hello_seen)return 0;if(!raya_ctl_nonce_equal(p+7,t->generation))return 0;if(raya_ctl_nonce_equal(p+23,t->supervisor_nonce))return 0;memcpy(t->worker_nonce,p+23,16);t->hello_seen=1;return 1;}
int raya_ctl_build_challenge(raya_ctl_transcript *t,uint8_t out[33]){if(!t||!out||!t->hello_seen||t->challenge_issued)return 0;out[0]=RAYA_CTL_CHALLENGE;memcpy(out+1,t->generation,16);memcpy(out+17,t->supervisor_nonce,16);t->challenge_issued=1;return 1;}
int raya_ctl_accept_binding(raya_ctl_transcript *t,const uint8_t *p,size_t n){if(!t||!raya_ctl_payload_valid(p,n)||p[0]!=RAYA_CTL_AUTH_BINDING||!t->hello_seen||!t->challenge_issued||t->binding_seen)return 0;if(!raya_ctl_nonce_equal(p+1,t->generation)||!raya_ctl_nonce_equal(p+17,t->worker_nonce)||!raya_ctl_nonce_equal(p+33,t->supervisor_nonce))return 0;t->binding_seen=1;return 1;}
int raya_ctl_mark_identity_verified(raya_ctl_transcript *t,int verified){if(!t||!t->hello_seen||!t->binding_seen||t->identity_verified||!verified)return 0;t->identity_verified=1;return 1;}
int raya_ctl_accept_ready(raya_ctl_transcript *t,const uint8_t *p,size_t n){if(!t||!raya_ctl_payload_valid(p,n)||p[0]!=RAYA_CTL_READY||!t->binding_seen||!t->identity_verified||t->ready_seen)return 0;if(!raya_ctl_nonce_equal(p+1,t->generation))return 0;t->ready_seen=1;return 1;}